app.post('/api/artifact-slots/equip', requireAuth, rateLimit('artifact-equip',30,10000),(req,res)=>{
    const playerId=String(req.telegramUser.id), itemName=String(req.body?.itemName||'');
    try{
        const tx=db.transaction(()=>{
            const row=db.prepare('SELECT data FROM players WHERE id=?').get(playerId);
            if(!row)return{success:false,error:'Игрок не найден'};
            const data=safeParsePlayerData(row.data);data.inventory=data.inventory||{};
            data.artifactSlots=Array.isArray(data.artifactSlots)?data.artifactSlots:[null,null,null,null,null,null];
            if((Number(data.inventory[itemName])||0)<=0)return{success:false,error:'Артефакта нет в инвентаре'};
            const art=serverArtifactDef(itemName);if(!art)return{success:false,error:'Неизвестный артефакт'};
            if(art.adminOnly&&playerId!==String(ADMIN_ID))return{success:false,error:'Артефакт только для администратора'};
            const requested=req.body?.index;
            if(requested!==undefined&&(!Number.isInteger(requested)||requested<0||requested>=6))
                return{success:false,error:'Некорректный слот'};
            const idx=requested===undefined?data.artifactSlots.findIndex(x=>!x):requested;
            if(idx<0)return{success:false,error:'Все 6 слотов заняты'};
            const oldName=data.artifactSlots[idx];
            const oldArt=oldName?serverArtifactDef(oldName):null;
            if(oldName&&!oldArt)return{success:false,error:'Не удалось определить надетый артефакт'};
            data.inventory[itemName]-=1;if(data.inventory[itemName]<=0)delete data.inventory[itemName];
            data.artifactSlots[idx]=itemName;
            if(oldName)pveAddItem(data,oldName,1,true);
            const capacityDelta={};
            for(const key of ['health','hunger','thirst'])
                capacityDelta[key]=(Number(art.stats?.[key])||0)-(Number(oldArt?.stats?.[key])||0);
            serverApplyArtifactCapacityDelta(data,capacityDelta,1);
            serverRecomputeArtifactDerived(playerId,data);
            db.prepare('UPDATE players SET data=?,last_seen=? WHERE id=?').run(JSON.stringify(data),Date.now(),playerId);
            return{success:true,state:serverEquipmentState(data),slot:idx};
        });
        return res.json(tx());
    }catch(e){console.error('[/api/artifact-slots/equip]',e);return res.status(500).json({success:false,error:'Ошибка надевания артефакта'});}
});
